query:
query Diablo4UgFeaturedDocumentQuery($input: Diablo4UserGeneratedDocumentInputBySlug!) {
  game: diablo4 {
    documents {
      userGeneratedDocumentBySlug(input: $input) {
        error
        data {
          ...NgfUgDocumentFragment
          ...Diablo4UgDocumentFragment
        }
      }
      userGeneratedDocumentTypes {
        error
        data {
          ...NgfDocumentTypeFragment
          ...NgfDocumentSpecificWidgetsSettingsFragment
        }
      }
      wikiDocumentType {
        error
        data {
          ...NgfWikiDocumentTypeFragment
        }
      }
    }
    permissions {
      ...NgfPermissionsFragment
    }
    settings {
      ...NgfGameSettingsFragment
    }
  }
}

